  NpcText joke;
  NpcText dry;

  Map<String, Object?> toJson() => {
        'flirt': flirt.toJson(),
        'joke': joke.toJson(),
        'dry': dry.toJson(),
      };
}

/// Vibe change per reply tone.
class NpcTones {
