        flirt: _int(j['flirt'], 'flirt'),
        joke: _int(j['joke'], 'joke'),
        dry: _int(j['dry'], 'dry'),
      );

  int flirt;
  int joke;
  int dry;

  Map<String, Object?> toJson() => {
        'flirt': flirt,
